mapper.select:
SELECT trace_id, tenant_id, user_id, session_id, selected_agent, selected_type, intent,
    complexity, success, fallback_used, task_count, duration_ms, question, reason, error, created_at
FROM agent_execution_trace WHERE tenant_id = #{tenantId}
AND user_id = #{userId}

    AND LOCATE(LOWER(#{query}), LOWER(CONCAT_WS(' ', question, selected_agent, selected_type,
        intent, user_id, trace_id, reason, error))) > 0




            AND (created_at < #{cursor.time} OR (created_at = #{cursor.time}
                AND trace_id < #{cursor.id}) OR created_at IS NULL)

        AND created_at IS NULL AND trace_id < #{cursor.id}


ORDER BY created_at DESC, trace_id DESC LIMIT #{limit}
